```go
func RunAgent(ctx context.Context, client *openai.Client, model string, messages []Message,
    tools []Tool, agentName, agentID, conversationID string) (*Response, error) {

    ctx, agentSpan := tracer.Start(ctx, "invoke_agent "+agentName,
        trace.WithSpanKind(trace.SpanKindClient),
        trace.WithAttributes(
            attribute.String("gen_ai.operation.name", "invoke_agent"),
            attribute.String("gen_ai.agent.name", agentName),
            attribute.String("gen_ai.agent.id", agentID),
            attribute.String("gen_ai.conversation.id", conversationID),
        ),
    )
    defer agentSpan.End()

    var totalInput, totalOutput int

    for {
        // chat span covers only the LLM inference
        chatCtx, chatSpan := tracer.Start(ctx, "chat "+model,
            trace.WithSpanKind(trace.SpanKindClient),
            trace.WithAttributes(
                attribute.String("gen_ai.operation.name", "chat"),
                attribute.String("gen_ai.system", "openai"),
                attribute.String("gen_ai.request.model", model),
                attribute.String("server.address", "api.openai.com"),
                attribute.Int("server.port", 443),
            ),
        )

        // Capture input messages for full conversation visibility
        inputJSON, _ := json.Marshal(messages)
        chatSpan.SetAttributes(attribute.String("gen_ai.input.messages", string(inputJSON)))

        resp, err := client.Chat(chatCtx, model, messages, tools)
        if err != nil {
            chatSpan.SetStatus(codes.Error, err.Error())
            chatSpan.SetAttributes(attribute.String("error.type", fmt.Sprintf("%T", err)))
            chatSpan.End()
            return nil, err
        }

        chatSpan.SetAttributes(
            attribute.String("gen_ai.response.model", resp.Model),
            attribute.StringSlice("gen_ai.response.finish_reasons", []string{resp.FinishReason}),
            attribute.Int("gen_ai.usage.input_tokens", resp.Usage.InputTokens),
            attribute.Int("gen_ai.usage.output_tokens", resp.Usage.OutputTokens),
        )
        totalInput += resp.Usage.InputTokens
        totalOutput += resp.Usage.OutputTokens

        // Capture output messages — model response + any tool call requests
        outputJSON, _ := json.Marshal(resp.Message)
        chatSpan.SetAttributes(attribute.String("gen_ai.output.messages", string(outputJSON)))

        chatSpan.End()
        // chat span is now closed

        if resp.FinishReason == "tool_calls" {
            for _, tc := range resp.ToolCalls {
                // execute_tool spans are siblings of chat, children of invoke_agent
                _, toolSpan := tracer.Start(ctx, "execute_tool "+tc.Name,
                    trace.WithSpanKind(trace.SpanKindInternal),
                    trace.WithAttributes(
                        attribute.String("gen_ai.operation.name", "execute_tool"),
                        attribute.String("gen_ai.tool.name", tc.Name),
                        attribute.String("gen_ai.tool.call.id", tc.ID),
                        attribute.String("gen_ai.agent.name", agentName),
                        attribute.String("gen_ai.conversation.id", conversationID),
                    ),
                )
                result, err := tools[tc.Name](ctx, tc.Args)
                if err != nil {
                    toolSpan.SetStatus(codes.Error, err.Error())
                    toolSpan.SetAttributes(attribute.String("error.type", fmt.Sprintf("%T", err)))
                }
                resultJSON, _ := json.Marshal(result)
                toolSpan.SetAttributes(attribute.String("gen_ai.tool.call.result", string(resultJSON)))
                toolSpan.End()

                messages = append(messages, Message{Role: "tool", ToolCallID: tc.ID, Content: string(resultJSON)})
            }
        } else {
            agentSpan.SetAttributes(
                attribute.Int("gen_ai.usage.input_tokens", totalInput),
                attribute.Int("gen_ai.usage.output_tokens", totalOutput),
            )
            return resp, nil
        }
    }
}
```

### Flushing After Agent Invocation

The tool-calling loop examples above produce spans buffered by `BatchSpanProcessor`.
**Always force-flush after the top-level agent call returns** to guarantee export.

#### Python

```python
# After the agent loop completes:
result = run_agent(client, model, messages, tools, "research-agent", "ra-1", "conv-123")
span_processor.force_flush()  # ensure all spans are exported
```

#### Node.js

```typescript
// After the agent loop completes:
const result = await runAgent(client, model, messages, tools, "research-agent", "ra-1", "conv-123");
await spanProcessor.forceFlush();  // ensure all spans are exported
```

#### Go

```go
// After the agent loop completes:
resp, err := RunAgent(ctx, client, model, messages, tools, "research-agent", "ra-1", "conv-123")
spanProcessor.ForceFlush(ctx) // ensure all spans are exported
```

Do NOT call `forceFlush()` inside the agent loop (per chat turn) — it adds unnecessary
latency. Flush once at the outer call boundary.

Resulting trace shape:
```
invoke_agent research-agent          (CLIENT)
├── chat gpt-4                       (CLIENT, inference #1)
├── execute_tool search_web          (INTERNAL)
├── chat gpt-4                       (CLIENT, inference #2)
├── execute_tool read_page           (INTERNAL)
└── chat gpt-4                       (CLIENT, final response)
```

## Pattern: Request Attributes Before, Response Attributes After

The general pattern for all GenAI spans:

1. **Before the call** — set on span creation:
   - `gen_ai.operation.name`, `gen_ai.system`, `gen_ai.request.model`
   - `gen_ai.request.max_tokens`, `gen_ai.request.temperature`
   - `server.address`, `server.port`

2. **After the call** — set on the span:
   - `gen_ai.response.id`, `gen_ai.response.model`
   - `gen_ai.response.finish_reasons`
   - `gen_ai.usage.input_tokens`, `gen_ai.usage.output_tokens`

3. **On error** — set on the span:
   - `error.type` (exception class name)
   - `span.set_status(ERROR)` / `span.SetStatus(codes.Error, ...)`

## Error Handling Best Practices

- Set a low-cardinality error dimension on **every** error path — `error.type` (exception class
  name or `ToolExecutionError`), `error=true`, and/or `exception.slug` as appropriate
- Set span status to ERROR
- For new diagnostic exception events, emit a Logs API record while the span is active with
  `event.name="exception"`, ERROR severity, and `exception.type`/`exception.message`/
  `exception.stacktrace` (plus `exception.escaped` when applicable)
- Logs API exception fields remain on the correlated event row, not the containing span. Agents
  should query `event.name=exception` with `trace.trace_id exists`, sample a trace ID, and call
  `get_trace(show_events=true)`; do not search only parent spans for `exception.*`
- Keep `span.record_exception(e)` / `span.RecordError(err)` for compatibility with existing
  SDKs and instrumentation where a usable Logs API is unavailable
- Let exceptions propagate — don't swallow errors silently

# Streaming Instrumentation

Instrumenting streaming GenAI responses (SSE, chunked responses) with proper span
lifecycle, timing metrics, and error handling.

## Span Lifecycle

A streaming span covers the **full stream lifetime** — from request start to final
chunk received. Usage attributes are set after the stream completes.

```
chat gpt-4  ─────────────────────────────────────►
             │         │    │    │    │         │
             request   first chunk  chunk     stream
             sent      chunk       ...        complete
                       ▲                      ▲
                       TTFC                   set usage attrs,
                                              end span
```

## Key Metrics

### Client-Side (Hosted APIs)

| Metric | Description | When to use |
| :--- | :--- | :--- |
| `gen_ai.client.operation.time_to_first_chunk` | Time from request to first streamed chunk (includes network) | Hosted APIs (OpenAI, Anthropic) |
| `gen_ai.client.operation.time_per_output_chunk` | Inter-chunk time (client-observed) | Measuring delivery consistency |

### Server-Side (Self-Hosted)

| Metric | Description | When to use |
| :--- | :--- | :--- |
| `gen_ai.server.time_to_first_token` | Server-side TTFT (queue + prefill time) | Self-hosted (vLLM, TGI) |
| `gen_ai.server.time_per_output_token` | Decode speed after first token | Self-hosted throughput |

**Client vs Server**: Client metrics include network latency; server metrics isolate
model performance. Use client metrics when calling hosted APIs, server metrics when
running your own inference server.

## Python Example

```python
import time
from opentelemetry import trace, metrics
from opentelemetry.trace import SpanKind, StatusCode

tracer = trace.get_tracer("genai-client")
meter = metrics.get_meter("genai-client")

ttfc_histogram = meter.create_histogram(
    "gen_ai.client.operation.time_to_first_chunk",
    unit="s",
    description="Time to first chunk from streaming GenAI response",
)

duration_histogram = meter.create_histogram(
    "gen_ai.client.operation.duration",
    unit="s",
    description="Total duration of GenAI operation",
)

def chat_stream(client, model, messages, conversation_id):
    with tracer.start_as_current_span(
        f"chat {model}",
        kind=SpanKind.CLIENT,
        attributes={
            "gen_ai.operation.name": "chat",
            "gen_ai.conversation.id": conversation_id,
            "gen_ai.system": "openai",
            "gen_ai.request.model": model,
            "server.address": "api.openai.com",
            "server.port": 443,
        },
    ) as span:
        start_time = time.monotonic()
        first_chunk_time = None
        collected_content = []
        input_tokens = 0
        output_tokens = 0

        try:
            stream = client.chat.completions.create(
                model=model, messages=messages, stream=True
            )

            for chunk in stream:
                if first_chunk_time is None and chunk.choices:
                    first_chunk_time = time.monotonic()
                    ttfc = first_chunk_time - start_time
                    ttfc_histogram.record(ttfc, {
                        "gen_ai.operation.name": "chat",
                        "gen_ai.request.model": model,
                    })

                if chunk.choices and chunk.choices[0].delta.content:
                    collected_content.append(chunk.choices[0].delta.content)

                # Usage comes in the final chunk
                if chunk.usage:
                    input_tokens = chunk.usage.prompt_tokens
                    output_tokens = chunk.usage.completion_tokens

                # Check for finish reason
                if chunk.choices and chunk.choices[0].finish_reason:
                    span.set_attribute(
                        "gen_ai.response.finish_reasons",
                        [chunk.choices[0].finish_reason],
                    )

            # Set usage after stream completes
            span.set_attribute("gen_ai.usage.input_tokens", input_tokens)
            span.set_attribute("gen_ai.usage.output_tokens", output_tokens)

            total_duration = time.monotonic() - start_time
            duration_histogram.record(total_duration, {
                "gen_ai.operation.name": "chat",
                "gen_ai.request.model": model,
            })

            return "".join(collected_content)

        except Exception as e:
            span.set_status(StatusCode.ERROR, str(e))
            span.set_attribute("error.type", type(e).__name__)
            raise
```

## Node.js Example

```javascript
const { trace, SpanKind, SpanStatusCode } = require("@opentelemetry/api");
const { metrics } = require("@opentelemetry/api");

const tracer = trace.getTracer("genai-client");
const meter = metrics.getMeter("genai-client");

const ttfcHistogram = meter.createHistogram(
  "gen_ai.client.operation.time_to_first_chunk",
  { unit: "s", description: "Time to first chunk" }
);

async function chatStream(client, model, messages, conversationId) {
  return tracer.startActiveSpan(
    `chat ${model}`,
    {
      kind: SpanKind.CLIENT,
      attributes: {
        "gen_ai.operation.name": "chat",
        "gen_ai.conversation.id": conversationId,
        "gen_ai.system": "openai",
        "gen_ai.request.model": model,
        "server.address": "api.openai.com",
        "server.port": 443,
      },
    },
    async (span) => {
      const startTime = performance.now();
      let firstChunkRecorded = false;
      const chunks = [];

      try {
        const stream = await client.chat.completions.create({
          model,
          messages,
          stream: true,
          stream_options: { include_usage: true },
        });

        for await (const chunk of stream) {
          if (!firstChunkRecorded && chunk.choices?.length > 0) {
            const ttfc = (performance.now() - startTime) / 1000;
            ttfcHistogram.record(ttfc, {
              "gen_ai.operation.name": "chat",
              "gen_ai.request.model": model,
            });
            firstChunkRecorded = true;
          }

          if (chunk.choices?.[0]?.delta?.content) {
            chunks.push(chunk.choices[0].delta.content);
          }

          if (chunk.usage) {
            span.setAttributes({
              "gen_ai.usage.input_tokens": chunk.usage.prompt_tokens,
              "gen_ai.usage.output_tokens": chunk.usage.completion_tokens,
            });
          }

          if (chunk.choices?.[0]?.finish_reason) {
            span.setAttribute(
              "gen_ai.response.finish_reasons",
              [chunk.choices[0].finish_reason]
            );
          }
        }

        return chunks.join("");
      } catch (e) {
        span.setStatus({ code: SpanStatusCode.ERROR, message: e.message });
        span.setAttribute("error.type", e.constructor.name);
        throw e;
      } finally {
        span.end();
      }
    }
  );
}
